-- Migration: Extend 7 math subjects to grade 12 (g6-12 curriculum)
-- Reuses existing subjects: numbers, geometry, measurement, logic,
--   algebra, trigonometry, statistics
-- Pattern follows 010: 10 topics × 3 difficulty variants = 30 lessons
--   per (subject, grade) for grades 6 through 12
-- Total new lessons: 1470 (7 subjects × 7 grades × 30 lessons)

BEGIN;

-- ============================================================
-- Extend existing subjects grade_max from 5 to 12
-- ============================================================
UPDATE subjects SET grade_max = 12 WHERE id = 'numbers' AND grade_max < 12;
UPDATE subjects SET grade_max = 12 WHERE id = 'geometry' AND grade_max < 12;
UPDATE subjects SET grade_max = 12 WHERE id = 'measurement' AND grade_max < 12;
